import json, glob
import pandas as pd

train_df = pd.read_parquet("/workspace/taco_verl/train.parquet")
test_df = pd.read_parquet("/workspace/taco_verl/test.parquet")

nl = chr(10)
def extract_q(text):
    if "QUESTION:" + nl in text:
        return text.split("QUESTION:" + nl, 1)[1].strip()
    return text.strip()

train_q_to_idx = {extract_q(r[0]["content"]): i for i, r in enumerate(train_df["prompt"])}
test_q_to_idx = {extract_q(r[0]["content"]): i for i, r in enumerate(test_df["prompt"])}

overlap = set(train_q_to_idx.keys()) & set(test_q_to_idx.keys())
print("Train-test question overlap:", len(overlap))

rollout_matched = 0
rollout_unmatched = 0
seen_train_indices = []
for s in range(1, 50):
    with open(f"/workspace/rollout_data/{s}.jsonl") as f:
        rows = [json.loads(line) for line in f]
    prompts_in_step = []
    for r in rows:
        q = extract_q(r["input"])
        if q.endswith(nl + "assistant"):
            q = q[:-len(nl + "assistant")].strip()
        if q in train_q_to_idx:
            rollout_matched += 1
            prompts_in_step.append(train_q_to_idx[q])
        else:
            rollout_unmatched += 1
    seen_train_indices.extend(set(prompts_in_step))

print(f"Rollout matched={rollout_matched}, unmatched={rollout_unmatched}")
print(f"Total unique train problems seen in 49 steps: {len(set(seen_train_indices))} (49*16 = {49*16})")
EOF

