import json
import glob
import pandas as pd
import numpy as np

train_df = pd.read_parquet("/workspace/taco_verl/train.parquet")
test_df = pd.read_parquet("/workspace/taco_verl/test.parquet")

nl = chr(10)
def extract_q(text):
    if "QUESTION:" + nl in text:
        q = text.split("QUESTION:" + nl, 1)[1]
        if nl + "assistant" in q:
            q = q.split(nl + "assistant", 1)[0]
        return q[:300].strip()
    return text[:300].strip()

train_q_to_idx = {extract_q(r[0]["content"]): i for i, r in enumerate(train_df["prompt"])}

prob_stats = {}
unmatched = 0
for p in sorted(glob.glob("/workspace/rollout_data/*.jsonl")):
    with open(p) as f:
        for line in f:
            row = json.loads(line)
            q = extract_q(row["input"])
            idx = train_q_to_idx.get(q)
            if idx is None:
                unmatched += 1
                continue
            if idx not in prob_stats:
                prob_stats[idx] = {"scores": [], "pass_rates": []}
            prob_stats[idx]["scores"].append(row["score"])
            prob_stats[idx]["pass_rates"].append(row.get("pass_rate", 0.0))

print(f"Unique train problems seen in 49 steps: {len(prob_stats)} / {len(train_df)} (unmatched={unmatched})")
