        if nl + "assistant" in q:
            q = q.split(nl + "assistant", 1)[0]
        return q[:300].strip()
    return text[:300].strip()

train_q_to_idx = {extract_q(r[0]["content"]): i for i, r in enumerate(train_df["prompt"])}

# Wait: let's check if ANY test in test.parquet has shuffled outputs!
# We have validation_data/0.jsonl .. 45.jsonl! Let's check test.parquet problems in validation_data!
test_q_to_idx = {extract_q(r[0]["content"]): i for i, r in enumerate(test_df["prompt"])}
val_stats = {}
for p in sorted(glob.glob("/workspace/validation_data/*.jsonl")):
    with open(p) as f:
        for line in f:
            row = json.loads(line)
            q = extract_q(row["input"])
            idx = test_q_to_idx.get(q)
            if idx not in val_stats:
                val_stats[idx] = {"scores": [], "pass_rates": []}
            val_stats[idx]["scores"].append(row["score"])
            val_stats[idx]["pass_rates"].append(row.get("pass_rate", 0.0))

print("Test problems with t_mismatch:")
for i, r in test_df.iterrows():
    gt = json.loads(r["reward_model"]["ground_truth"])
    inps, outs = gt["inputs"], gt["outputs"]
    tm = 0
    for inp, out in zip(inps, outs):
        il = str(inp).strip().splitlines()
        ol = str(out).strip().splitlines()
        if len(il) >= 2 and il[0].strip().isdigit():
            T = int(il[0].strip())
            if len(il) == T + 1 and len(ol) != T:
                tm += 1
    if tm > 0:
        st = val_stats.get(i, {"scores": [], "pass_rates": []})
        print(f"  test idx={i}, pid={r['extra_info']['problem_id']}, n_tests={len(inps)}, tm={tm}, max_score={max(st['scores'])}, max_pr={max(st['pass_rates'])}")
