import json
import glob
import pandas as pd
import numpy as np

train_df = pd.read_parquet("/workspace/taco_verl/train.parquet")
nl = chr(10)
def extract_q(text):
    if "QUESTION:" + nl in text:
        q = text.split("QUESTION:" + nl, 1)[1]
        if nl + "assistant" in q:
            q = q.split(nl + "assistant", 1)[0]
        return q[:300].strip()
    return text[:300].strip()

train_q_to_idx = {extract_q(r[0]["content"]): i for i, r in enumerate(train_df["prompt"])}

prob_stats = {}
for p in sorted(glob.glob("/workspace/rollout_data/*.jsonl")):
    with open(p) as f:
        for line in f:
            row = json.loads(line)
            q = extract_q(row["input"])
            idx = train_q_to_idx.get(q)
            if idx not in prob_stats:
                prob_stats[idx] = {"scores": [], "pass_rates": []}
            prob_stats[idx]["scores"].append(row["score"])
            prob_stats[idx]["pass_rates"].append(row.get("pass_rate", 0.0))

# Let's check for each seen problem with n_tests in [2, 50], what is its max_score and max_pr!
rows = []
for i, r in train_df.iterrows():
    st = prob_stats.get(i)
    if not st:
        continue
    rows.append({
        "idx": i,
        "pid": r["extra_info"]["problem_id"],
        "n_tests": r["extra_info"]["n_tests"],
        "code_type": r["extra_info"]["code_type"],
        "mean_score": np.mean(st["scores"]),
        "max_score": np.max(st["scores"]),
        "mean_pr": np.mean(st["pass_rates"]),
        "max_pr": np.max(st["pass_rates"]),
    })
sdf = pd.DataFrame(rows)
for lo, hi in [(1, 1), (2, 5), (6, 10), (11, 20), (21, 50), (51, 100), (101, 1000)]:
    sub = sdf[(sdf["n_tests"] >= lo) & (sdf["n_tests"] <= hi)]
    # How many have max_score == 0? How many have max_score == 0 but max_pr > 0?
    ms0 = (sub["max_score"] == 0).sum()
    ms0_pr_pos = ((sub["max_score"] == 0) & (sub["max_pr"] > 0)).sum()
    print(f"n_tests [{lo:3d}, {hi:4d}]: total={len(sub):3d}, solved={(sub['max_score']>0).sum():3d} ({(sub['max_score']>0).mean()*100:5.1f}%), unsolved={ms0:3d} (with pr>0: {ms0_pr_pos:3d})")
EOF

