            # Check up to 2 rollouts per problem
            is_perm_prob = False
            gt = json.loads(r["reward_model"]["ground_truth"])
            inps, outs = gt["inputs"], gt["outputs"]
            if len(inps) > 30:
                # only check first 30 if too many, wait: if it's a permutation of all N, we need all N or check if each actual_out is in expected_outs!
