import json, glob
import pandas as pd

train_df = pd.read_parquet("/workspace/taco_verl/train.parquet")
test_df = pd.read_parquet("/workspace/taco_verl/test.parquet")

# Map prompt -> problem_id and row index
prompt_to_idx = {r["prompt"][0]["content"]: i for i, r in train_df.iterrows()}

rollout_stats = {}
for f in sorted(glob.glob("/workspace/rollout_data/*.jsonl")):
    with open(f) as fh:
        for line in fh:
            d = json.loads(line)
            # prompt in rollout_data is chat-formatted string; let's extract user content
            p = d["input"]
            start = p.find("<|im_start|>user")
            end = p.find("<|im_end|>", start)
            if start != -1 and end != -1:
                user_c = p[start + len("<|im_start|>user") + 1 : end]
                idx = prompt_to_idx.get(user_c)
                if idx is not None:
                    st = rollout_stats.setdefault(idx, {"n": 0, "pos": 0, "scores": []})
                    st["n"] += 1
                    if d["score"] > 0.5:
                        st["pos"] += 1
                    st["scores"].append(d["score"])

def classify_prompt(p):
    if "-----Input-----" in p:
        return "-----Input----- (Codeforces)"
    if "SAMPLE INPUT" in p:
        return "SAMPLE INPUT (HackerEarth)"
    if "Sample Input" in p:
        return "Sample Input (AtCoder/CodeChef)"
    if "Example" in p:
        return "Example (LeetCode/etc)"
    if "INPUT" in p:
        return "INPUT"
    return "Other"

for cat in ["-----Input----- (Codeforces)", "SAMPLE INPUT (HackerEarth)", "Sample Input (AtCoder/CodeChef)", "Example (LeetCode/etc)", "INPUT", "Other"]:
    idxs = [i for i, r in train_df.iterrows() if classify_prompt(r["prompt"][0]["content"]) == cat]
    seen = [i for i in idxs if i in rollout_stats]
    solved = [i for i in seen if rollout_stats[i]["pos"] > 0]
    n_gt1 = [i for i in seen if train_df.loc[i, "extra_info"]["n_tests"] > 1]
    solved_gt1 = [i for i in n_gt1 if rollout_stats[i]["pos"] > 0]
    print(f"{cat:32s}: total={len(idxs):4d}, seen={len(seen):3d}, solved={len(solved):3d} ({len(solved)/max(1,len(seen)):.1%}) | n_tests>1: seen={len(n_gt1):3d}, solved={len(solved_gt1):3d} ({len(solved_gt1)/max(1,len(n_gt1)):.1%})")
EOF

