import json
import glob
import subprocess
import sys
import pandas as pd
from verl.utils.reward_score.taco import post_process

nl = chr(10)
train_df = pd.read_parquet("/workspace/taco_verl/train.parquet")
with open("/tmp/known_he_perms.json") as f:
    all_perms = {int(k): v for k, v in json.load(f).items()}

he_gt1 = [i for i, r in train_df.iterrows() if "SAMPLE INPUT" in r["prompt"][0]["content"] and int(r["extra_info"]["n_tests"]) > 1]
rem = [i for i in he_gt1 if i not in all_perms]

prompt_to_idx = {r["prompt"][0]["content"]: i for i, r in train_df.iterrows()}
rem_set = set(rem)

idx_to_codes = {i: [] for i in rem}
marker = "<|im_start|>user" + nl
end_marker = "<|im_end|>" + nl + "<|im_start|>assistant"

for path in sorted(glob.glob("/workspace/rollout_data/*.jsonl")):
    with open(path) as f:
        for line in f:
            row = json.loads(line)
            p = row["input"]
            if marker in p and end_marker in p:
                u = p.split(marker, 1)[1].split(end_marker, 1)[0]
                idx = prompt_to_idx.get(u)
                if idx in rem_set:
                    code = post_process(row["output"])
                    if code and code not in idx_to_codes[idx]:
                        idx_to_codes[idx].append(code)

seen_rem = [i for i in rem if idx_to_codes[i]]
print("Seen remaining:", len(seen_rem))

def norm_tokens(s):
    return tuple(s.split())

def norm_lines(s):
    return nl.join(line.strip() for line in s.strip().splitlines())

recovered_relaxed = {}
partial_stats = []

for idx in seen_rem:
    r = train_df.loc[idx]
    gt = json.loads(r["reward_model"]["ground_truth"])
    inps = gt["inputs"]
    outs = gt["outputs"]
    outs_nl = [norm_lines(o) for o in outs]
    outs_tok = [norm_tokens(o) for o in outs]

    best_match = 0
    for code in idx_to_codes[idx]:
        pred_nl = []
        pred_tok = []
        for inp in inps:
            try:
                p = subprocess.run([sys.executable, "-c", code], input=inp, text=True, capture_output=True, timeout=2.0)
                if p.returncode != 0:
                    pred_nl.append(None)
                    pred_tok.append(None)
                else:
                    pred_nl.append(norm_lines(p.stdout))
                    pred_tok.append(norm_tokens(p.stdout))
            except Exception:
                pred_nl.append(None)
                pred_tok.append(None)
        if None not in pred_tok and sorted(pred_tok) == sorted(outs_tok) and len(set(outs_tok)) == len(outs_tok):
            perm = [outs_tok.index(pt) for pt in pred_tok]
            recovered_relaxed[idx] = perm
            best_match = len(inps)
            break
        # Count how many non-None pred_tok match a unique element in outs_tok
        m = sum(1 for pt in pred_tok if pt is not None and outs_tok.count(pt) == 1)
        if m > best_match:
            best_match = m
    partial_stats.append((idx, r["extra_info"]["problem_id"], len(inps), len(set(outs_tok)), best_match))

print("Recovered via token/timeout match:", len(recovered_relaxed))
for idx, pid, n, u_out, bm in sorted(partial_stats, key=lambda x: (x[2]-x[4], -x[4]))[:35]:
    print(f"  idx={idx:4d} pid={pid:10s} n={n:2d} unique_outs={u_out:2d} best_unique_match={bm:2d}")
