with open('/tmp/known_he_perms.json') as f:
  all_perms = {int(k): v for k, v in json.load(f).items()}

solvers = {}


def s_4(inp):
  lines = inp.split()
  if not lines:
    return ''
  T = int(lines[0])
  out = []
  idx = 1
  for _ in range(T):
    a, b, c = int(lines[idx]), int(lines[idx + 1]), int(lines[idx + 2])
    idx += 3
    if b < 0:
      val = 0
    else:
      val = a**b
    q = val // c
    c1 = q * c
    c2 = (q + 1) * c
    if abs(val - c1) <= abs(c2 - val):
      out.append(str(c1))
    else:
      out.append(str(c2))
  return NL.join(out)


solvers[4] = s_4


def s_8(inp):
  parts = inp.split()
  N, P = int(parts[0]), int(parts[1])
  p = P / 100.0
  dp = [0.0] * (N + 4)
  dp[0] = 1.0
  for i in range(N):
    if dp[i] > 0:
      dp[i + 2] += dp[i] * p
      dp[i + 3] += dp[i] * (1.0 - p)
  return f'{dp[N]:.6f}'


solvers[8] = s_8


def s_10(inp):
  parts = inp.split()
  N = int(parts[0])
  a = [int(x) for x in parts[1 : N + 1]]
  dp = [1] * N
  for i in range(N):
    ai = abs(a[i])
    si = 1 if a[i] > 0 else -1
    best = 1
    for j in range(i):
      if abs(a[j]) < ai and (1 if a[j] > 0 else -1) != si:
        if dp[j] + 1 > best:
          best = dp[j] + 1
    dp[i] = best
  return str(max(dp) if dp else 0)


solvers[10] = s_10


def s_15(inp):
  parts = inp.split()
  T = int(parts[0])
  idx = 1
  out = []
  for _ in range(T):
    E = int(parts[idx])
    idx += 1
    cities = set()
    for _ in range(E):
      cities.add(int(parts[idx]))
      cities.add(int(parts[idx + 1]))
      idx += 2
    out.append(str(len(cities)))
  return NL.join(out)


